  ('employees', 'Employees', 'VSME B8 and B10 workforce characteristics, representation, training, and workforce policies.', 20),
  ('energy', 'Energy', 'VSME B3 energy consumption, sources, greenhouse gas indicators, and reduction initiatives.', 30),
