  ('waste', 'Waste', 'VSME B7 resource use, circular economy, waste streams, and contractor evidence.', 50),
  ('environmental_policies', 'Environmental Policies', 'VSME B2, B4, B5, and B6 environmental practices, impacts, water, and initiatives.', 60),
